"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["31913"],{41487(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.obrigatoriedade_legal.modalidades_minimas_vazia","status":422,"titulo":"Exig\xeancia de modalidades m\xednimas sem nenhuma modalidade"},"descricao":{"codigo":"uniplus.selecao.obrigatoriedade_legal.modalidades_minimas_vazia","requisitos":["UNI-REQ-0018"],"oQueAconteceu":["A regra \xe9 do tipo **modalidades m\xednimas** (`$tipo` `modalidadesMinimas`) \u2014 exige que o processo\\nofere\xe7a um conjunto de modalidades \u2014, e a lista `codigos` do predicado n\xe3o serve. Duas situa\xe7\xf5es\\ncaem aqui, e a viola\xe7\xe3o \xe9 apontada no campo `predicado`:","- a lista veio ausente, nula ou vazia;\\n- a lista tem ao menos um item nulo, vazio ou s\xf3 com espa\xe7os.","Um c\xf3digo preenchido que n\xe3o existe no cadastro n\xe3o \xe9 o caso: ele passa por esta confer\xeancia e \xe9\\nrecusado depois, por\\n[`modalidade_nao_encontrada`](/erros/uniplus.selecao.obrigatoriedade_legal.modalidade_nao_encontrada).","Uma lista vazia \xe9 satisfeita por qualquer processo, inclusive por um que n\xe3o\\nofere\xe7a modalidade alguma: n\xe3o h\xe1 nada a conferir. A cl\xe1usula legal ficaria\\naprovada por vacuidade, e o edital publicaria sob uma exig\xeancia que na pr\xe1tica\\nn\xe3o existe.","\xc9 o oposto do que a regra pretende: quem cadastra modalidades m\xednimas quer\\njustamente impedir a publica\xe7\xe3o de um processo que n\xe3o as ofere\xe7a. Um item em\\nbranco no meio da lista tem o mesmo efeito sobre aquele item: a compara\xe7\xe3o \xe9 por\\nigualdade exata e o vazio nunca casa.","A confer\xeancia \xe9 de forma e sai antes de qualquer consulta ao cadastro. Como as\\ndemais viola\xe7\xf5es de campo, ela volta junto com elas em `errors[]`, com status 422."],"comoResolver":["Liste ao menos uma modalidade e preencha todos os itens da lista \u2014 ou remova a\\nregra, se a exig\xeancia n\xe3o se aplica ao tipo de processo."],"ondeAparece":["Cadastro de uma obrigatoriedade legal","Atualiza\xe7\xe3o de uma obrigatoriedade legal"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Obrigatoriedade legal"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"2b5f8240ef92ed3147f41ca40a325e729f45c7bd"}}')}}]);